_⚠️ Potential issue_ | _🟠 Major_ | _⚡ Quick win_

**Missing option values can crash parsing or propagate invalid state.**

Line 101 (`argv[++i]!.toLowerCase()`), Line 253, and Line 270 assume a next token exists. For trailing options (for example `--import-from`, `--workspace`, `--destination`), this can throw at runtime or assign `undefined` into required state fields.

<details>
<summary>Suggested fix</summary>

```diff
 function consumeNext(
@@
   return {
     matches: (arg) => forms.includes(arg),
-    apply: (arg, argv, i, state) => apply(arg, argv, i, state) + 1,
+    apply: (arg, argv, i, state) => {
+      if (i + 1 >= argv.length) {
+        throw new Error(`Missing value for ${arg}`);
+      }
+      return apply(arg, argv, i, state) + 1;
+    },
   };
 }
@@
     apply: (arg, argv, i, state) => {
-      const value = arg.startsWith(eqForm)
-        ? arg.slice(eqForm.length)
-        : argv[++i]!;
+      const value = arg.startsWith(eqForm)
+        ? arg.slice(eqForm.length)
+        : (i + 1 < argv.length ? argv[++i]! : (() => { throw new Error(`Missing value for ${forms[0]}`); })());
       apply(arg, value, state);
       return i + 1;
     },
   };
 }
@@
     apply: (arg, argv, i, state) => {
       const raw = arg.startsWith(eqForm)
         ? arg.slice(eqForm.length)
-        : argv[++i]!;
+        : (i + 1 < argv.length ? argv[++i]! : (() => { throw new Error(`Missing value for ${forms[0]}`); })());
       apply(arg, Number(raw), state);
       return i + 1;
     },
   };
 }
```
</details>




Also applies to: 251-254, 268-271

